            for i in range(100)
        ]
        status, payload = self.post_apply(tx_document(*entries))
        self.assertEqual(status, 201)
        self.assertEqual((payload["accepted"], payload["replayed"]), (100, 0))
        _, metrics = self.get_metrics()
